export function propFromNative(data: any): Prop {
  return {
    kind: data.kind as PropKind,
    a: data.a,
    b: data.b,
    c: data.c,
    d: data.d,
    text: data.text,
    node: data.node,
  };
}

/** The kinds of `Prop`, each with the fields it reads. */
export const Prop = {
  unset(): Prop {
    return { kind: PropKind.UNSET, a: 0, b: 0, c: 0, d: 0, text: "", node: 0 };
  },
  number(a: number = 0): Prop {
    return { kind: PropKind.NUMBER, a, b: 0, c: 0, d: 0, text: "", node: 0 };
  },
  bool(a: number = 0): Prop {
    return { kind: PropKind.BOOL, a, b: 0, c: 0, d: 0, text: "", node: 0 };
  },
  triple(a: number = 0, b: number = 0, c: number = 0): Prop {
    return { kind: PropKind.TRIPLE, a, b, c, d: 0, text: "", node: 0 };
  },
  text(text: string = ""): Prop {
    return { kind: PropKind.TEXT, a: 0, b: 0, c: 0, d: 0, text, node: 0 };
  },
  corners(a: number = 0, b: number = 0, c: number = 0, d: number = 0): Prop {
    return { kind: PropKind.CORNERS, a, b, c, d, text: "", node: 0 };
  },
  null_(): Prop {
    return { kind: PropKind.NULL, a: 0, b: 0, c: 0, d: 0, text: "", node: 0 };
  },
  node(node: number = 0): Prop {
    return { kind: PropKind.NODE, a: 0, b: 0, c: 0, d: 0, text: "", node };
  },
};

// How a transition plays: the argument of `transition_begin` and `transition_animate`. A struct that starts with `size` may
// grow.
export interface TransitionOptions {
  autoplay: number;
  easing: number;
  durationMs: number;
  delayMs: number;
}

export function transitionOptionsToNative(value: Init<TransitionOptions>): Record<string, unknown> {
  return {
    autoplay: value.autoplay,
    easing: value.easing,
    duration_ms: value.durationMs,
    delay_ms: value.delayMs,
  };
}

export function transitionOptionsFromNative(data: any): TransitionOptions {
  return {
    autoplay: data.autoplay,
    easing: data.easing,
    durationMs: data.duration_ms,
    delayMs: data.delay_ms,
  };
}

// What a transition is now: filled by `transition_info`.
export interface TransitionInfo {
  state: number;
  id: number;
  durationMs: number;
  progress: number;
  paused: number;
  reversed: number;
}

export function transitionInfoToNative(value: Init<TransitionInfo>): Record<string, unknown> {
  return {
    state: value.state,
    id: value.id,
    duration_ms: value.durationMs,
    progress: value.progress,
    paused: value.paused,
    reversed: value.reversed,
  };
}

export function transitionInfoFromNative(data: any): TransitionInfo {
  return {
    state: data.state,
    id: data.id,
    durationMs: data.duration_ms,
    progress: data.progress,
    paused: data.paused,
    reversed: data.reversed,
  };
}

// One element of a style list: a border, a shadow or a filter. The `kind` (`STD_ENTRY_*`) says which fields are read.
export interface StyleEntry {
  kind: EntryKind;
  inset: number;
  a: number;
  b: number;
  c: number;
  d: number;
  color: string;
}

export function styleEntryToNative(value: Init<StyleEntry>): Record<string, unknown> {
  return {
    kind: value.kind,
    inset: value.inset,
    a: value.a,
    b: value.b,
    c: value.c,
    d: value.d,
    color: value.color,
  };
}

export function styleEntryFromNative(data: any): StyleEntry {
  return {
    kind: data.kind as EntryKind,
    inset: data.inset,
    a: data.a,
    b: data.b,
    c: data.c,
    d: data.d,
    color: data.color,
  };
}

/** The kinds of `StyleEntry`, each with the fields it reads. */
export const StyleEntry = {
  border(a: number = 0, b: number = 0, color: string = "", inset: number = 0): StyleEntry {
    return { kind: EntryKind.BORDER, inset, a, b, c: 0, d: 0, color };
  },
  shadow(a: number = 0, b: number = 0, c: number = 0, d: number = 0, color: string = "", inset: number = 0): StyleEntry {
    return { kind: EntryKind.SHADOW, inset, a, b, c, d, color };
  },
  blur(a: number = 0): StyleEntry {
    return { kind: EntryKind.BLUR, inset: 0, a, b: 0, c: 0, d: 0, color: "" };
  },
  saturate(a: number = 0): StyleEntry {
    return { kind: EntryKind.SATURATE, inset: 0, a, b: 0, c: 0, d: 0, color: "" };
  },
  brightness(a: number = 0): StyleEntry {
    return { kind: EntryKind.BRIGHTNESS, inset: 0, a, b: 0, c: 0, d: 0, color: "" };
  },
  contrast(a: number = 0): StyleEntry {
    return { kind: EntryKind.CONTRAST, inset: 0, a, b: 0, c: 0, d: 0, color: "" };
  },
};

// The functions of a layout the shell implements. Every function gets the layout's `user` first.
export interface Layout {
  // Places the workspace's tiled clients. Pure: the same context and the same options give the same placements.
  compute(cx: LayoutContext): Init<Placement>[];
  // A client joined the workspace.
  clientAdded?(cx: LayoutContext, client: number): void;
  // A client left the workspace.
  clientRemoved?(cx: LayoutContext, client: number): void;
  // The workspace's area changed.
  areaChanged?(old: Rect, new_: Rect): void;
  // Two clients traded places in the workspace's order.
  clientsSwapped?(a: number, b: number): void;
  // The layout's revision: absent means the layout never changes by itself and the shell calls `workspace_invalidate`.
  revision?(): number;
  // The divider a drag that pressed a client at a point would move. Absent: the layout has no dividers.
  findSplit?(client: number, x: number, y: number): Init<Split> | null;
  // Moves the dividers `find_split` returned.
  setSplit?(token: number, ratio: number, crossRatio: number): void;
  // Puts the dividers `find_split` returned back as they were.
  resetSplit?(token: number): void;
}

export function layoutToNative(target: Layout): Record<string, unknown> {
  const table: Record<string, unknown> = {};
  {
    table.compute = (cx: any) => (target.compute!(layoutContextFromNative(cx)) ?? []).map(placementToNative);
  }
  if (typeof target.clientAdded === "function") {
    table.client_added = (cx: any, client: any) => target.clientAdded!(layoutContextFromNative(cx), client);
  }
  if (typeof target.clientRemoved === "function") {
    table.client_removed = (cx: any, client: any) => target.clientRemoved!(layoutContextFromNative(cx), client);
  }
  if (typeof target.areaChanged === "function") {
    table.area_changed = (old: any, new_: any) => target.areaChanged!(rectFromNative(old), rectFromNative(new_));
  }
  if (typeof target.clientsSwapped === "function") {
    table.clients_swapped = (a: any, b: any) => target.clientsSwapped!(a, b);
  }
  if (typeof target.revision === "function") {
    table.revision = () => target.revision!();
  }
  if (typeof target.findSplit === "function") {
    table.find_split = (client: any, x: any, y: any) => ((found) => (found == null ? null : splitToNative(found)))(target.findSplit!(client, x, y));
  }
  if (typeof target.setSplit === "function") {
    table.set_split = (token: any, ratio: any, crossRatio: any) => target.setSplit!(token, ratio, crossRatio);
  }
  if (typeof target.resetSplit === "function") {
    table.reset_split = (token: any) => target.resetSplit!(token);
  }
  return table;
}
